// The daemon requests' pure parts: the curl arguments for the sasy-watch
// daemon's routes (the settings hooks' own payloads), and how the daemon's
// answer to a policy check becomes a `classic.PreToolUse` result. register.tsx
// makes the calls, since only it may hold the engine interface.
import type { PreToolUseResult } from 'claude-code'

export const DEFAULT_PORT = '51711'
export const CHECK_TIMEOUT_MS = 12_000
export const ENSURE_TIMEOUT_MS = 10_000

/** What the daemon is asked about one tool call: the settings hook's stdin. */
export type CheckInput = {
  session_id: string
  tool_name: string
  tool_input: Record<string, unknown>
  tool_use_id: string
  cwd: string
  transcript_path?: string
  /** A subagent's id, as the hook receives it for a subagent's call. */
  agent_id?: string
  /** The caller's agent type: a subagent's, or a session started with --agent. */
  agent_type?: string
  /** The session's permission mode (`default`, `acceptEdits`, `plan`, ...), as
   *  of the latest prompt or finished tool call; the hook receives it the same
   *  way. Left out until the mod has seen it. */
  permission_mode?: string
  /** Marks the mod, so a daemon that supports it adds the bypass offer for the
   *  mod's own dialog (`sasyApproval`); an older daemon ignores it. */
  sasy_mod: true
}

/** What the daemon is told about the host, as the hook plugin's scripts tell
 *  it: Claude Code's entrypoint (`cli`, `claude-vscode`, ...) and the terminal
 *  program. The daemon logs both and uses the entrypoint to detect the host. */
export type HostHeaders = { entrypoint: string; term: string }

/** A value safe in a header line: no control characters, at most 64
 *  characters (the scripts' `header_safe`). */
export function headerSafe(value: string | undefined): string {
  return (value ?? '').replace(/[\u0000-\u001f\u007f]/g, '').slice(0, 64)
}

/** A one-time bypass the daemon offers on a denial, for the mod's own dialog. */
export type BypassOffer = {
  /** The daemon-authored question, ending in its `[SASY-ALLOW:…]` routing tag. */
  question: string
  /** The canonical choices: approve, decline, and trust-domain when offered. */
  labels: string[]
  /** The policy's reason as the user should read it. */
  reason: string
  /** The policy's reason with its suggested fix, as the model should read it. */
  policyReason: string
  /** The domain trust-domain would trust for the session, when offered. */
  domain?: string
}

/** A check's answer: the decision, and the bypass the daemon offers with it. */
export type CheckAnswer = { result: PreToolUseResult; offer?: BypassOffer }

/** The daemon's two choice lists: without and with a host to trust. */
const PLAIN_LABELS = ['approve', 'decline']
const TRUST_LABELS = ['approve', 'decline', 'trust-domain']
/** Whether `labels` is exactly `expected`, element by element. */
const isExactly = (labels: unknown[], expected: string[]): boolean =>
  labels.length === expected.length && labels.every((label, i) => label === expected[i])
/** A host the daemon names for session trust, as it derives one: 3 to 253
 *  characters of [a-z0-9.-], with at least one dot between labels. */
const DOMAIN = /^(?=.{3,253}$)[a-z0-9-]+(\.[a-z0-9-]+)+$/
/** The daemon's routing tag, which ends every question it asks. */
const ROUTING_TAG = /\[SASY-ALLOW:[0-9a-f]+\]$/
/** What the dialog removes before drawing a question (invisible and control
 *  characters, as register.tsx's CONTROL). */
const HIDDEN = /[\p{Cc}\p{Cf}\p{Default_Ignorable_Code_Point}\u2800]/gu
/** Whether a question says something the user can read besides its tag. */
const isReadable = (question: string): boolean =>
  /[\p{L}\p{N}]/u.test(question.replace(ROUTING_TAG, '').replace(HIDDEN, ''))

/** The `sasyApproval` field of a daemon answer, or undefined when it is not one. */
function offerOf(value: unknown): BypassOffer | undefined {
  if (!isRecord(value)) return undefined
  const { question, labels, reason, policyReason, domain, ...unknown } = value
  const isValid =
    Object.keys(unknown).length === 0 &&
    typeof question === 'string' && ROUTING_TAG.test(question) && isReadable(question) &&
    typeof reason === 'string' &&
    typeof policyReason === 'string' &&
    Array.isArray(labels) &&
    (domain === undefined
      ? isExactly(labels, PLAIN_LABELS)
      : typeof domain === 'string' && DOMAIN.test(domain) && isExactly(labels, TRUST_LABELS))
  if (!isValid) return undefined
  return {
    question: question as string,
    labels: labels as string[],
    reason: reason as string,
    policyReason: policyReason as string,
    ...(domain === undefined ? {} : { domain: domain as string }),
  }
}

/**
 * curl's arguments for one POST to the daemon: bounded in time and size, never
 * via a proxy, the body on stdin, the HTTP status appended on a line of its
 * own. A daemon that authenticates hooks is sent its header file with
 * `-H @file`, so the secret never appears in a process's arguments.
 */
export function postArgv(
  port: string,
  authFile: string | undefined,
  route: string,
  maxSeconds: number,
  retrySeconds = 0,
  host: HostHeaders = { entrypoint: '', term: '' },
): string[] {
  // Retries, when asked for, also cover HTTP errors (a daemon whose policy
  // engine is still starting answers 400), one a second, for at most
  // retrySeconds in all (curl restarts --max-time for each attempt).
  const retry =
    retrySeconds === 0
      ? []
      : [
          '--fail', '--retry', String(retrySeconds), '--retry-delay', '1',
          '--retry-max-time', String(retrySeconds), '--retry-all-errors',
        ]
  return [
    'curl', '-sS', '--noproxy', '*', '--max-time', String(maxSeconds), ...retry,
    '--max-filesize', '1048576', '-X', 'POST', '-H', 'content-type: application/json',
    '-H', `x-claude-code-entrypoint: ${headerSafe(host.entrypoint) || 'unknown'}`,
    '-H', `x-claude-code-term-program: ${headerSafe(host.term)}`,
    ...(authFile === undefined ? [] : ['-H', `@${authFile}`]),
    '--data-binary', '@-', '--write-out', '\n%{http_code}',
    `http://127.0.0.1:${port}${route}`,
  ]
}

/** curl's arguments for one policy check (/v1/pretooluse). */
export function checkArgv(port: string, authFile: string | undefined, host?: HostHeaders): string[] {
  return postArgv(port, authFile, '/v1/pretooluse', 10, 0, host)
}

/** Splits curl's output into the body and the HTTP status it appended. */
export function splitStatus(stdout: string): { body: string; status: string } {
  const cut = stdout.lastIndexOf('\n')
  return { body: stdout.slice(0, Math.max(cut, 0)), status: stdout.slice(cut + 1) }
}

const isRecord = (v: unknown): v is Record<string, unknown> =>
  typeof v === 'object' && v !== null && !Array.isArray(v)

/**
 * The daemon's hook output as a `classic.PreToolUse` result, or undefined when
 * it is not one. The accepted shapes are exactly the daemon's: `{}` (no
 * objection), or `{ hookSpecificOutput }` with `hookEventName: "PreToolUse"`,
 * an optional decision with its reason, and an optional input rewrite and
 * context note, each of its own type, with at least one of decision, rewrite
 * or note. Anything else fails closed rather than passing a call the backup
 * hook would then skip.
 */
export function toResult(body: string): PreToolUseResult | undefined {
  return parseAnswer(body)?.result
}

/**
 * A daemon answer as the decision and, beside a denial, the one-time bypass it
 * offers (`sasyApproval`, sent only to a client that set `sasy_mod`). Undefined
 * when the answer is not one of the daemon's exact shapes: that fails closed.
 */
export function parseAnswer(body: string): CheckAnswer | undefined {
  let out: unknown
  try {
    out = JSON.parse(body)
  } catch {
    return undefined
  }
  if (!isRecord(out)) return undefined
  const { sasyApproval, ...rest } = out
  const keys = Object.keys(rest)
  const offer = sasyApproval === undefined ? undefined : offerOf(sasyApproval)
  if (sasyApproval !== undefined && offer === undefined) return undefined
  if (keys.length === 0) return offer === undefined ? { result: {} } : undefined
  if (keys.length !== 1 || !isRecord(rest.hookSpecificOutput)) return undefined
  const result = decisionOf(rest.hookSpecificOutput)
  if (result === undefined) return undefined
  // An offer rides only on a denial.
  if (offer !== undefined && result.deny === undefined) return undefined
  return offer === undefined ? { result } : { result, offer }
}

/** A `hookSpecificOutput` block as a `classic.PreToolUse` result, or undefined. */
function decisionOf(block: Record<string, unknown>): PreToolUseResult | undefined {
  const {
    hookEventName,
    permissionDecision: decision,
    permissionDecisionReason: reason,
    updatedInput,
    additionalContext: note,
    ...unknown
  } = block
  const isValid =
    Object.keys(unknown).length === 0 &&
    hookEventName === 'PreToolUse' &&
    (decision === undefined || decision === 'allow' || decision === 'ask' || decision === 'deny') &&
    (reason === undefined || typeof reason === 'string') &&
    (updatedInput === undefined || isRecord(updatedInput)) &&
    (note === undefined || typeof note === 'string') &&
    (decision !== undefined || updatedInput !== undefined || note !== undefined)
  if (!isValid) return undefined
  const why = typeof reason === 'string' ? reason : ''
  const decided: PreToolUseResult =
    decision === 'deny'
      ? { deny: why || '[SASY] denied by policy' }
      : decision === 'ask'
        ? { ask: why || '[SASY] approval needed' }
        : {} // an `allow` too: SASY never skips Claude Code's own permission prompt
  return {
    ...decided,
    ...(isRecord(updatedInput) ? { updatedInput } : {}),
    ...(typeof note === 'string' && note !== '' ? { additionalContext: [note] } : {}),
  }
}

/** SASY's denial, keeping the context notes other hooks added to the call. */
export function denyWith(ours: PreToolUseResult & { deny: string }, theirs: PreToolUseResult): PreToolUseResult {
  const context = [...(ours.additionalContext ?? []), ...(theirs.additionalContext ?? [])]
  return { deny: ours.deny, ...(context.length === 0 ? {} : { additionalContext: context }) }
}

/** One answer from several PreToolUse deciders: deny over ask over allow. */
export function combine(ours: PreToolUseResult, theirs: PreToolUseResult): PreToolUseResult {
  const context = [...(ours.additionalContext ?? []), ...(theirs.additionalContext ?? [])]
  // SASY's rewrite is part of what it authorised, so it wins over another
  // hook's rewrite of the same call.
  const updatedInput = ours.updatedInput ?? theirs.updatedInput
  if (theirs.deny !== undefined) return denyWith({ ...theirs, deny: theirs.deny }, ours)
  const extra = {
    ...(updatedInput === undefined ? {} : { updatedInput }),
    ...(context.length === 0 ? {} : { additionalContext: context }),
  }
  if (ours.ask !== undefined) return { ask: ours.ask, ...extra }
  if (theirs.ask !== undefined) return { ask: theirs.ask, ...extra }
  if (theirs.allow === true) return { allow: true, ...extra }
  return extra
}

/** curl exits that mean the daemon did not answer: could not connect (7),
 *  partial reply (18), timed out (28), empty reply (52), the connection dropped
 *  while sending (55) or receiving (56). */
export const UNREACHABLE_CURL_EXITS = [7, 18, 28, 52, 55, 56]

/** A check's reply: the daemon's body, or why there is none and of what kind. */
export type CheckReply = { body: string } | { error: string; kind: 'unreachable' | 'auth' | 'answer' }

/** What a check's curl run came to. Only a daemon that is down or not
 *  answering is "unreachable" (the one failure SASY_FAIL_OPEN covers); curl
 *  failing otherwise, as on an auth header file it cannot read, is not. */
export function replyOf(ran: { exitCode: number; stdout: string }, port: string): CheckReply {
  if (ran.exitCode !== 0) {
    const kind = UNREACHABLE_CURL_EXITS.includes(ran.exitCode) ? 'unreachable' : 'answer'
    return { error: `curl exit ${ran.exitCode} on port ${port}`, kind }
  }
  const { body, status } = splitStatus(ran.stdout)
  if (status === '200') return { body }
  const kind = status === '401' || status === '403' ? 'auth' : 'answer'
  return { error: `sasy-watch answered HTTP ${status}`, kind }
}

/** A command whose run fails sooner than this never started. */
export const SPAWN_FAILURE_MS = 2000

files.hooks/text.ts:
// Pure text helpers: what the mod draws, prints and records, held to the
// shapes the daemon sends and stripped of what could disguise it. Split from
// the hooks module, which keeps everything that talks to Claude Code.
import type { PreToolUseResult } from 'claude-code'

import type { GuardCounts, GuardDecision, GuardVerdict } from '../types'
import type { BypassOffer } from './enforce'

/** The most characters of a call's target the band and /guard show. */
export const TARGET_CHARS = 80
/** Where the policy's own words start in a hook's text. */
export const MARKER = '[SASY]'
const REASON_CHARS = 4000

/** What the model is told at SessionStart, as the hook plugin's script says it. */
export const SESSION_NOTE =
  'SASY policy enforcement is active for this session. Tool calls are checked against ' +
  'a security policy; denied calls return a [SASY] reason — relay it to the user and ' +
  'follow its suggested fix rather than retrying or working around it.'

/** The tool-call fields that name what a call acts on, in order of preference. */
export const TARGET_FIELDS = ['command', 'file_path', 'notebook_path', 'url', 'path', 'pattern']

/** Control and format characters (C0 and C1 controls other than newline and
 *  tab, bidirectional marks, tags), every default-ignorable code point (zero-
 *  width characters, variation selectors, fillers that draw as nothing), and
 *  the blank Braille pattern: whatever could make a drawn command or path look
 *  like a different one or hide it. */
export const CONTROL =
  /(?![\n\t])[\p{Cc}\p{Cf}\p{Default_Ignorable_Code_Point}\u2800]/gu

export function shorten(text: string, max: number): string {
  const flat = text.replace(/\s+/g, ' ').replace(CONTROL, '').trim()
  return flat.length <= max ? flat : `${flat.slice(0, max - 1)}…`
}

export function targetOf(e: Readonly<Record<string, unknown>>): string {
  for (const field of TARGET_FIELDS) {
    const value = e[field]
    if (typeof value === 'string' && value !== '') return shorten(value, TARGET_CHARS)
  }
  return ''
}

/**
 * A policy reason as the band and /guard show it: control characters other
 * than newline and tab removed, and held to REASON_CHARS. The model has already
 * read the same text as the call's result; this keeps the session's own copy
 * small and free of terminal escapes.
 */
export function cleanReason(text: string): string {
  const clean = text.replace(CONTROL, '').trim()
  return clean.length <= REASON_CHARS ? clean : `${clean.slice(0, REASON_CHARS - 1)}…`
}

/** The sasy-guard verdict in a PreToolUse result, or none for any other. */
export function verdictOf(result: PreToolUseResult): { verdict: GuardVerdict; reason: string } | null {
  const pairs: [GuardVerdict, string | undefined][] = [
    ['deny', result.deny],
    ['ask', result.ask],
  ]
  for (const [verdict, text] of pairs) {
    // The engine may wrap the hook's text (`PreToolUse:Bash hook error: ...`);
    // the policy's own words start at the marker.
    const at = text?.indexOf(MARKER) ?? -1
    if (text !== undefined && at >= 0) {
      return { verdict, reason: cleanReason(text.slice(at + MARKER.length)) }
    }
  }
  return null
}

export function statusText(c: GuardCounts): string {
  return `${c.checked} checked · ${c.denied} denied · ${c.asked} asked`
}

export function clockTime(ms: number): string {
  return new Date(ms).toTimeString().slice(0, 8)
}

/** What the dialog's buttons say, by the daemon's canonical choice. */
export function choiceLabels(offer: BypassOffer): Record<string, string> {
  return {
    approve: 'Approve once',
    decline: 'Deny',
    ...(offer.domain === undefined ? {} : { 'trust-domain': `Trust ${offer.domain} for this session` }),
  }
}

/**
 * Text that must keep its end: the question ends with what is being approved
 * (`Attempted: ...`) and the policy reason with its fix. Control characters
 * are removed as for every reason; past REASON_CHARS the middle goes.
 */
function cleanKeepingEnd(text: string): string {
  const clean = text.replace(CONTROL, '').trim()
  if (clean.length <= REASON_CHARS) return clean
  const tail = Math.floor(REASON_CHARS * 0.6)
  return `${clean.slice(0, REASON_CHARS - tail - 3)} … ${clean.slice(-tail)}`
}

/** The offer's daemon-authored texts as the mod draws every reason. */
export function cleanOffer(offer: BypassOffer): BypassOffer {
  return {
    ...offer,
    question: cleanKeepingEnd(offer.question),
    reason: cleanReason(offer.reason),
    policyReason: cleanKeepingEnd(offer.policyReason),
  }
}

/** The /healthz fields /guard prints, each held to the shape the daemon sends. */
/** An endpoint /guard may print: a DNS host name, an IPv4 address or a
 *  bracketed IPv6 address, and a port. Anything else is not printed. */
const ENDPOINT =
  /^(?=.{1,259}$)([A-Za-z0-9-]{1,63}(\.[A-Za-z0-9-]{1,63})*|\[[0-9a-fA-F:]{2,39}\]):\d{1,5}$/
const FAIL_MODES = ['open', 'closed']

/** One decision for /guard: a heading, then its reason, whole or first line. */
export function decisionLines(d: GuardDecision, isWhole: boolean): string[] {
  const head = `  ${clockTime(d.at)}  ${d.verdict.padEnd(8)}  ${d.tool}  ${d.target}`
  const reason = d.reason.split('\n').filter(line => line.trim() !== '')
  const body = isWhole ? reason : reason.slice(0, 1).map(line => shorten(line, 120))
  return [head.trimEnd(), ...body.map(line => `            ${line}`)]
}

/** The line /guard prints for a /healthz answer (curl's output, the HTTP
 *  status on its last line): only values in the daemon's own shapes. */
export function healthLine(url: string, stdout: string): string {
  const cut = stdout.lastIndexOf('\n')
  const status = stdout.slice(cut + 1)
  if (!/^[0-9]{3}$/.test(status)) return `daemon: ${url} gave no HTTP status`
  if (status !== '200') return `daemon: ${url} answered HTTP ${status}`
  let h: unknown
  try {
    h = JSON.parse(stdout.slice(0, Math.max(cut, 0)))
  } catch {
    return `daemon: ${url} answered with a body that is not JSON`
  }
  const r = (typeof h === 'object' && h !== null ? h : {}) as Record<string, unknown>
  const isDaemon =
    r.ok === true &&
    typeof r.ready === 'boolean' &&
    typeof r.endpoint === 'string' &&
    ENDPOINT.test(r.endpoint) &&
    typeof r.failMode === 'string' &&
    FAIL_MODES.includes(r.failMode) &&
    Number.isInteger(r.sessions) &&
    (r.sessions as number) >= 0
  if (!isDaemon) return `daemon: ${url} answered, but not as the sasy-watch daemon`
  const state = r.ready ? 'up, policy engine ready' : 'up, policy engine not ready'
  return (
    `daemon: ${state} · endpoint ${r.endpoint} · ` +
    `fail mode ${r.failMode} · ${r.sessions} session(s)`
  )
}

/** The `additionalContext` a daemon answer carries, if any. */
export function contextOf(answer: string | undefined): string[] {
  if (answer === undefined) return []
  try {
    const out = JSON.parse(answer) as { hookSpecificOutput?: { additionalContext?: unknown } }
    const note = out.hookSpecificOutput?.additionalContext
    return typeof note === 'string' && note !== '' ? [note] : []
  } catch {
    return []
  }
}

/** The band shows the policy's reason and fix; /guard has the rest. */
const BAND_REASON_LINES = 3

/** How the band draws a decision: its verb and colour, and the reason lines
 *  that fit (the heading, a possible overflow line and the button take the
 *  other rows). */
export function bandLines(
  d: GuardDecision,
  maxRows: number,
): { verb: string; color: string; shown: string[] } {
  const verb = {
    deny: 'denied',
    ask: 'needs approval for',
    approved: 'asked you, and you allowed',
    declined: 'asked you, and blocked',
  }[d.verdict]
  const color = { deny: 'red', ask: 'yellow', approved: 'green', declined: 'red' }[d.verdict]
  const room = Math.max(1, Math.min(BAND_REASON_LINES, maxRows - 3))
  const reason = d.reason.split('\n').filter(line => line.trim() !== '')
  const shown = reason.slice(0, room)
  if (reason.length > room) shown.push('… full text: /guard')
  return { verb, color, shown }
}

/** The decisions /guard lists, newest first. */
const RECENT_IN_COMMAND = 5

/** What /guard prints: the daemon's health line, this session's totals, and
 *  the most recent decisions, the newest in full. */
export function guardText(health: string, c: GuardCounts, decisions: GuardDecision[]): string {
  const recent = decisions.slice(-RECENT_IN_COMMAND).reverse()
  const lines = [health, `this session: ${c.checked} checked · ${c.denied} denied · ${c.asked} asked`]
  if (recent.length === 0) lines.push('no denials or approval requests yet')
  else lines.push('recent decisions (newest first):', ...recent.flatMap((d, i) => decisionLines(d, i === 0)))
  return lines.join('\n')
}

/** What the mod's own dialog came to, for the record: the offer the user
 *  answered (its reason) and whether they approved. */
export type DialogRecord = { verdict: GuardVerdict; reason: string }
/** What became of one approval dialog: the call's result and what to record
 *  (absent when the outcome is an ordinary SASY denial). */
export type DialogOutcome = { result: PreToolUseResult; record?: DialogRecord }

